namespace {std::atomic<std::uint64_t> allocationCount{};}
void* operator new(std::size_t size){allocationCount.fetch_add(1,std::memory_order_relaxed);if(void* memory=std::malloc(size?size:1))return memory;throw std::bad_alloc();}

