    FootPlacement3D transformed;if(!transformed.Prepare(skeleton,map,map.compatibility))return Fail("transformed prepare");const Matrix4 root=CreateTransformMatrix({.1f,.2f,0},{0,0,.12f},{1,1,1}),model=CreateTransformMatrix({.5f,0,-.5f},{0,.35f,0},{1.2f,1.2f,1.2f}),worldToModel=CreateScaleMatrix({1.f/1.2f,1.f/1.2f,1.f/1.2f})*CreateRotationMatrix({0,-.35f,0})*CreateTranslationMatrix({-.5f,0,.5f});FootPlacementFrame3D tf;tf.heightField=&terrain;tf.poseRoot=root;tf.modelToWorld=model;tf.worldToModel=worldToModel;AnimationPose3D tp;for(int i=0;i<30;++i){tp=Bind(skeleton,root);if(!transformed.Evaluate(skeleton,map,tf,tp,&result))return Fail("transformed evaluate");}const Vec3 solvedLeft=TransformPoint(model,TransformPoint(tp.globalMatrices[6],{}));if(Length(solvedLeft-result.left.targetWorld)>.002f){std::fprintf(stderr,"transformed error=%f solved=(%f,%f,%f) target=(%f,%f,%f)\n",Length(solvedLeft-result.left.targetWorld),solvedLeft.x,solvedLeft.y,solvedLeft.z,result.left.targetWorld.x,result.left.targetWorld.y,result.left.targetWorld.z);return Fail("transformed foot error exceeded 2mm");}
