    FootPlacement3D scalePlacement,scaleTwin;if(!scalePlacement.Prepare(skeleton,map,map.compatibility)||!scaleTwin.Prepare(skeleton,map,map.compatibility))return Fail("scale prepare");FootPlacementFrame3D scaleFrame;scaleFrame.heightField=&terrain;scaleFrame.modelToWorld=CreateScaleMatrix({1,2,1});scaleFrame.worldToModel=CreateScaleMatrix({1,.5f,1});auto scalePose=Bind(skeleton),scaleBefore=scalePose;FootPlacementResult3D scaleOut{};scaleOut.ikSolves=91;if(scalePlacement.Evaluate(skeleton,map,scaleFrame,scalePose,&scaleOut)||!Same(scalePose,scaleBefore)||scaleOut.ikSolves!=91)return Fail("nonuniform scale atomic failed");scaleFrame.modelToWorld=scaleFrame.worldToModel=Matrix4::Identity();auto scaleA=Bind(skeleton),scaleB=Bind(skeleton);FootPlacementResult3D outA{},outB{};if(!scalePlacement.Evaluate(skeleton,map,scaleFrame,scaleA,&outA)||!scaleTwin.Evaluate(skeleton,map,scaleFrame,scaleB,&outB)||!Same(scaleA,scaleB)||std::memcmp(&outA,&outB,sizeof outA))return Fail("failed alignment advanced hidden state");
    FootPlacement3D disabledInvalid;if(!disabledInvalid.Prepare(skeleton,map,map.compatibility))return Fail("disabled invalid prepare");FootPlacementFrame3D disabledFrame;disabledFrame.heightField=&terrain;auto disabledPose=Bind(skeleton);FootPlacementResult3D disabledState{};if(!disabledInvalid.Evaluate(skeleton,map,disabledFrame,disabledPose,&disabledState)||disabledState.left.weight<=0)return Fail("disabled invalid setup");const float retainedWeight=disabledState.left.weight;disabledFrame.cameraDistance=100;auto reject=[&](Matrix4 matrix,Matrix4 inverse){disabledFrame.modelToWorld=matrix;disabledFrame.worldToModel=inverse;auto candidate=Bind(skeleton),before=candidate;FootPlacementResult3D sentinel{};sentinel.ikSolves=123;return !disabledInvalid.Evaluate(skeleton,map,disabledFrame,candidate,&sentinel)&&Same(candidate,before)&&sentinel.ikSolves==123;};if(!reject(CreateScaleMatrix({1,2,1}),CreateScaleMatrix({1,.5f,1})))return Fail("disabled nonuniform accepted");Matrix4 shear=Matrix4::Identity(),inverseShear=Matrix4::Identity();shear[0][1]=.2f;inverseShear[0][1]=-.2f;if(!reject(shear,inverseShear))return Fail("disabled shear accepted");Matrix4 perspective=Matrix4::Identity(),inversePerspective=Matrix4::Identity();perspective[3][0]=.1f;inversePerspective[3][0]=-.1f;if(!reject(perspective,inversePerspective))return Fail("disabled perspective accepted");disabledFrame.modelToWorld=disabledFrame.worldToModel=Matrix4::Identity();disabledFrame.cameraDistance=2;disabledFrame.heightField=nullptr;disabledPose=Bind(skeleton);if(!disabledInvalid.Evaluate(skeleton,map,disabledFrame,disabledPose,&disabledState)||disabledState.left.weight<=0||disabledState.left.weight>=retainedWeight)return Fail("disabled invalid advanced hidden state");
