    CollisionWorld3D platformWorld;const auto platform=platformWorld.CreateBox({{{0,-.5f,0},{2,.1f,2}},1,CollisionLayerAll3D,9001,false});FootPlacement3D moving;if(!moving.Prepare(skeleton,map,map.compatibility))return Fail("moving prepare");FootPlacementFrame3D pf;pf.collisionWorld=&platformWorld;pf.cameraDistance=2;MovingPlatformSample3D sample;sample.collider=platform;sample.userData=9001;pf.movingPlatforms={&sample,1};auto pp=Bind(skeleton);if(!moving.Evaluate(skeleton,map,pf,pp,&result)||result.left.source!=FootContactSource3D::Collider)return Fail("platform contact failed");const float oldX=result.left.contactWorld.x;sample.currentLocalToWorld=CreateTranslationMatrix({.25f,0,0});sample.currentWorldToLocal=CreateTranslationMatrix({-.25f,0,0});pf.cameraDistance=40;pf.frameIndex=1;pp=Bind(skeleton);if(!moving.Evaluate(skeleton,map,pf,pp,&result)||std::abs(result.left.contactWorld.x-oldX-.25f)>.002f)return Fail("platform mapping failed");const float platformWeight=result.left.weight;if(!platformWorld.Destroy(platform))return Fail("platform destroy failed");pf.movingPlatforms={};pf.frameIndex=2;pp=Bind(skeleton);if(!moving.Evaluate(skeleton,map,pf,pp,&result)||result.left.weight>=platformWeight||result.left.collider)return Fail("lost platform did not release on reduced frame");
